CREATE TABLE IF NOT EXISTS docs(col TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated INTEGER NOT NULL,PRIMARY KEY(col,id));
CREATE INDEX IF NOT EXISTS docs_col_upd ON docs(col,updated);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT,status TEXT NOT NULL DEFAULT 'pending',created INTEGER,last_login INTEGER);
CREATE TABLE IF NOT EXISTS otp(email TEXT PRIMARY KEY,code_hash TEXT,expires INTEGER,tries INTEGER DEFAULT 0,sent INTEGER,name TEXT);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER,created INTEGER);
CREATE TABLE IF NOT EXISTS mail_log(id TEXT PRIMARY KEY,at INTEGER,kind TEXT,to_addr TEXT,subject TEXT,ok INTEGER,err TEXT);
CREATE TABLE IF NOT EXISTS reminders(key TEXT PRIMARY KEY,at INTEGER);
